 signal (correlated multivariate normal)\\n    mean_normal: np.ndarray = np.zeros(n_features)\\n    cov_normal: np.ndarray = np.diag([1.0, 0.5, 0.8, 0.2])\\n    X_normal: np.ndarray = rng.multivariate_normal(mean_normal, cov_normal, size=n_samples)\\n\\n    # Determine number of anomalies\\n    n_anomalies: int = int(n_samples * anomaly_ratio)\\n    y: np.ndarray = np.zeros(n_samples, dtype=int)\\n\\n    # Select random indices for anomalies\\n    anomaly_indices: np.ndarray = rng.choice(\\n        n_samples, size=n_anomalies, replace=False\\n    )\\n\\n    # Inject anomalies by shifting means and increasing variance (simulating pathological states)\\n    X_anomaly: np.ndarray = X_normal[anomaly_indices].copy()\\n    # Shift mean for each feature differently to simulate multi-modal stress\\n    shift_magnitude: float = 3.5\\n    shifts: np.ndarray = rng.uniform(-1, 1, size=n_features) * shift_magnitude\\n    X_anomaly += shifts\\n    # Increase noise for anomalous segments\\n    X_anomaly += rng.normal(0, 2.0, size=X_anomaly.shape)\\n\\n    # Place anomalies back into the main array\\n    X: np.ndarray = X_normal.copy()\\n    X[anomaly_indices] = X_anomaly\\n    y[anomaly_indices] = 1\\n\\n    return X, y\\n\\n\\ndef _evaluate_metrics(\\n    y_true: np.ndarray,\\n    y_pred: np.ndarray\\n) -> AnomalyMetrics:\\n    \"\"\"Compute precision, recall, F1-score, and false alarm rate.\\n\\n    Args:\\n        y_true: Ground truth binary labels.\\n        y_pred: Predicted binary labels.\\n\\n    Returns:\\n        AnomalyMetrics instance containing computed scores.\\n    \"\"\"\\n    # True Positives (TP), False Positives (FP), False Negatives (FN)\\n    tp = int(np.sum((y_true == 1) & (y_pred == 1)))\\n    fp = int(np.sum((y_true == 0) & (y_pred == 1)))\\n    fn = int(np.sum((y_true == 1) & (y_pred == 0)))\\n\\n    # Precision: TP / (TP + FP)\\n    precision: float = tp / (tp + fp) if (tp + fp) > 0 else 0.0\\n\\n    # Recall: TP / (TP + FN)\\n    recall: float = tp / (tp + fn) if (tp + fn) > 0 else 0.0\\n\\n    # F1-Score: 2 * (Precision * Recall) / (Precision + Recall)\\n    f1_score: float = (\\n        2 * precision * recall / (precision + recall)\\n        if (precision + recall) > 0\\n        else 0.0\\n    )\\n\\n    # False Alarm Rate (FAR): FP / (FP + TN) -> specifically for healthy subjects labeled as anomaly\\n    tn = int(np.sum((y_true == 0) & (y_pred == 0)))\\n    false_alarm_rate: float = fp / (fp + tn) if (fp + tn) > 0 else 0.0\\n\\n    return AnomalyMetrics(\\n        precision=precision,\\n        recall=recall,\\n        f1_score=f1_score,\\n        false_alarm_rate=false_alarm_rate\\n    )\\n\\n\\ndef train_and_evaluate(\\n    csv_out_path: str = 'results.csv',\\n    seed: int = 42\\n) -> Dict[str, Dict[str, float]]:\\n    \"\"\"Execute comparative evaluation against baseline and proposed detectors.\\n\\n    Generates synthetic bio-signals using `generate_biosignal_dataset`, applies\\n    both the static Z-score baseline and the adaptive robust Mahalanobis-ensemble\\n    detector, and saves the results to a CSV file.\\n\\n    The comparison highlights:\\n    1. Baseline: Univariate Z-Score per feature with threshold Z_THRESHOLD.\\n    2. Proposed: Adaptive Robust Mahalanobis Distance estimated via an Ensemble\\n       of covariance matrices (simulating robustness to outliers).\\n\\n    Args:\\n        csv_out_path: Destination path for the empirical benchmark metrics CSV.\\n        seed: Deterministic RNG seed (default: 42).\\n\\n    Returns:\\n        Dictionary mapping model names ('baseline', 'proposed') to their metric dictionaries.\\n    \"\"\"\\n    # 1. Generate Data\\n    X, y_true = generate_biosignal_dataset(\\n        n_samples=N_SAMPLES,\\n        anomaly_ratio=ANOMALY_RATIO,\\n        seed=seed\\n    )\\n    n_features: int = X.shape[1]\\n    results: Dict[str, Dict[str, float]] = {}\\n\\n    # 2. Baseline: Static Univariate Z-Score\\n    # Calculate mean and std per feature using robust statistics to avoid contamination bias in baseline?\\n    # Standard approach: use global stats. To keep it simple and standard:\\n    feat_means: np.ndarray = np.mean(X, axis=0)\\n    feat_stds: np.ndarray = np.std(X, axis=0) + 1e-8  # Avoid division by zero\\n\\n    # Z-Score for each point\\n    z_scores: np.ndarray = np.abs((X - feat_means) / feat_stds)\\n    # If any feature exceeds threshold, mark as anomaly\\n    y_pred_baseline: np.ndarray = (z_scores.max(axis=1) > Z_THRESHOLD).astype(int)\\n\\n    metrics_baseline: AnomalyMetrics = _evaluate_metrics(y_true, y_pred_baseline)\\n    results['baseline'] = {\\n        'precision': metrics_baseline.precision,\\n        'recall': metrics_baseline.recall,\\n        'f1_score': metrics_baseline.f1_score,\\n        'false_alarm_rate': metrics_baseline.false_alarm_rate\\n    }\\n\\n    # 3. Proposed: Adaptive Robust Mahalanobis-Ensemble\\n    # We simulate an ensemble of robust covariance estimators by bootstrapping subsets\\n    # of the data to learn local inliers, then averaging their Mahalanobis distances.\\n    \\n    ensemble_distances: List[np.ndarray] = []\\n    n_bootstraps: int = ENSEMBLE_TREES  # Use defined constant\\n    rng_ens: np.random.Generator = np.random.default_rng(seed + 1) # Different seed for ensemble\\n\\n    sample_size: int = N_SAMPLES // 2\\n\\n    for _ in range(n_bootstraps):\\n        # Bootstrap a subset of the data to estimate local covariance\\n        indices = rng_ens.choice(N_SAMPLES, size=sample_size, replace=False)\\n        X_subset: np.ndarray = X[indices]\\n\\n        # Compute mean and robust covariance for this subset\\n        mu_sub: np.ndarray = np.mean(X_subset, axis=0)\\n        cov_sub: np.ndarray = np.cov(X_subset, rowvar=False)\\n        \\n        # Add regularization to ensure invertibility (shrinkage)\\n        reg_cov: np.ndarray = cov_sub + 1e-4 * np.eye(n_features)\\n        try:\\n            inv_cov_sub: np.ndarray = np.linalg.inv(reg_cov)\\n        except np.linalg.LinAlgError:\\n            # Fallback to identity if singular\\n            inv_cov_sub: np.ndarray = np.eye(n_features)\\n\\n        # Calculate Mahalanobis distance for ALL points against this local model\\n        diffs: np.ndarray = X - mu_sub\\n        # Mahalanobis squared: d^2 = (x-mu)^T * S^-1 * (x-mu)\\n        left_side: np.ndarray = diffs @ inv_cov_sub\\n        dist_sq: np.ndarray = np.sum(left_side * diffs, axis=1)\\n        \\n        ensemble_distances.append(dist_sq)\\n\\n    # Average distances across the ensemble\\n    avg_mahalanobis_dist: np.ndarray = np.mean(ensemble_distances, axis=0)\\n\\n    # Determine threshold dynamically based on the median of normal-ish data or percentile\\n    # For fair comparison with baseline which is static, we use a percentile-based cutoff\\n    # on the training distribution itself (simulating unsupervised calibration)\\n    threshold_percentile: float = np.percentile(avg_mahalanobis_dist, 100 * (1 - ANOMALY_RATIO))\\n    y_pred_proposed: np.ndarray = (avg_mahalanobis_dist > threshold_percentile).astype(int)\\n\\n    metrics_proposed: AnomalyMetrics = _evaluate_metrics(y_true, y_pred_proposed)\\n    results['proposed'] = {\\n        'precision': metrics_proposed.precision,\\n        'recall': metrics_proposed.recall,\\n        'f1_score': metrics_proposed.f1_score,\\n        'false_alarm_rate': metrics_proposed.false_alarm_rate\\n    }\\n\\n    # 4. Save to CSV\\n    try:\\n        import pandas as pd\\n        df = pd.DataFrame([results['baseline'], results['proposed']])\\n        df.index.name = 'model'\\n        df.to_csv(csv_out_path)\\n    except ImportError:\\n        # Fallback if pandas is not strictly required for the environment, though standard in stack\\n        import csv\\n        with open(csv_out_path, 'w', newline='') as f:\\n            writer = csv.writer(f)\\n            header = ['model'] + list(results['baseline'].keys())\\n            writer.writerow(header)\\n            for model_name, metrics in results.items():\\n                row = [model_name] + list(metrics.values())\\n                writer.writerow(row)\\n\\n    return results\\n",
  "summary": "Fixed core.py by ensuring strict type annotations, deterministic seeding, and operational logic for the bio-signal anomaly detection pipeline. Includes synthetic data generation (generate_biosignal_dataset), metric evaluation (_evaluate_metrics), and comparative training/evaluation against Z-score and Mahalanobis-ensemble baselines (train_and_evaluate)."
